mapper.update:
CREATE TABLE IF NOT EXISTS ${database}.${subTable}
USING ${database}.${superTable}
TAGS (#{deviceTag})

mapper.select:
SELECT
    ts,event_ts,device_name,point_id,point_code,rule_id,rule_name,alarm_level,event_type,message,value_text,value_double,value_long,value_bool,unit,payload_json
FROM ${database}.${subTable}
WHERE 1 = 1

    AND point_id = #{pointId}


    AND point_code = #{pointCode}


    AND alarm_level = #{alarmLevel}


    AND rule_id = #{ruleId}


    AND ts >= #{startTs}


    AND ts <= #{endTs}

ORDER BY ts DESC
LIMIT #{limit}
